    if (i >= objectCount())
      break;
    if (!enabled(i))
      continue;
    if (isShell(i) ? side(p, lowLevel(i)) > 0. && side(p, highLevel(i)) < 0.
                   : side(p, objectLevel(i)) > 0.)
