  for (int i = 0; i < 3; i++) {
    if (i >= objectCount())
      break;
    if ((mask & (1 << i)) == 0)
      continue;
    float w = isShell(i) ? highLevel(i) - lowLevel(i) : 1. - objectLevel(i);
    if (w <= width) {
      width = w;
      id = i;
