float sceneHit(vec3 o, vec3 d, out float level, out float normalSign, out int id) {
  float best = -1.;
  level = 0.;
  normalSign = -1.;
  id = -1;
  for (int i = 0; i < 3; i++) {
    if (i >= objectCount())
      break;
    if (!enabled(i))
      continue;
    float lo = isShell(i) ? lowLevel(i) : objectLevel(i), s = intersection(o, d, lo);
    if (s >= 0. && (best < 0. || s < best)) {
      best = s;
      level = lo;
      normalSign = -1.;
      id = i;
    }
    if (isShell(i)) {
      s = intersection(o, d, highLevel(i));
      if (s >= 0. && (best < 0. || s < best)) {
