        (1. - smoothstep(.20, .23, abs(az + .32))) * (1. - smoothstep(.25, .28, abs(el - .12)));
    float box2 =
        (1. - smoothstep(.07, .09, abs(az - .40))) * (1. - smoothstep(.32, .35, abs(el - .06)));
    col += vec3(2.8, 2.9, 3.1) * box1 + vec3(5., 3.9, 2.7) * box2 + vec3(.65, .78, 1.) * ceiling;
