    vec3 sun = normalize(vec3(-1., .10, -.35));
    col += vec3(8., 4.3, 1.5) * pow(max(0., dot(d, sun)), 900.);
    col += vec3(.32, .13, .06) * pow(max(0., dot(d, sun)), 12.);
  }
  if (uEnvironment == 5) {
    col = vec3(.07, .09, .12);
