  float ct = sqrt(max(0., 1. - st2));
  float rs = (n1 * ci - n2 * ct) / max(1e-7, n1 * ci + n2 * ct);
  float rp = (n1 * ct - n2 * ci) / max(1e-7, n1 * ct + n2 * ci);
