      o = p + n * eps;
      d = r;
      roughness = mat.z;
      continue;
    }
    light += weight * F * roughEnvironment(r, mat.z);
    weight *= 1. - F;
    if (tangent) {
      o = p + d * eps * 4.;
      continue;
    }
    mask = nextMask;
    o = p - n * eps;
    d = normalize(t);
    roughness = 0.;
