}
float form(vec4 a, vec4 b, float level) {
  return dot(a, (uP - mat4(level)) * b);
}
// Small shells need smaller origin offsets AND a smaller positive-root
// cutoff. Widely separated boundaries use the upper bias limit.
float rayBiasScale() {
  if (uRayBias > 0.)
    return uRayBias;
