    vec2 sum=vec2(0);
    for(int j=0;j<4;++j) {
      vec2 a=dsSub(vec2(uP[j][i],0.),vec2(i==j?level:0.,0.));
      sum=dsAdd(sum,dsMul(a,dsGet(v,j)));
