  b=dsVScale(direction,invL*2.);
  dsSet(b,3,dsDot(scaled,direction)*2.);
  DS4 top=dsVector(vec4(0)); dsSet(top,3,dsDot(direction,direction));
  if(farChart){a=top;c=base;}else{a=base;c=top;}
