  vec2 u=dsDiv(dsSub(a,s3),s3);
  vec2 correction=dsMul(u,dsAdd(dsDiv(vec2(1,0),vec2(3,0)),
    dsMul(u,dsAdd(dsDiv(vec2(-1,0),vec2(9,0)),dsMul(u,dsDiv(vec2(5,0),vec2(81,0)))))));
  return dsMul(vec2(s,0),dsAdd(vec2(1,0),correction));
