void gdSinCos(vec2 x,out vec2 s,out vec2 c) {
  vec2 xx=-dsMul(x,x),st=x,ct=vec2(1,0);s=st;c=ct;
  // |x|<=pi: 18 terms, well below the paired-arithmetic error floor.
  for(int i=1;i<=18;++i){
    st=dsDiv(dsMul(st,xx),vec2(float(2*i*(2*i+1)),0));
    ct=dsDiv(dsMul(ct,xx),vec2(float((2*i-1)*2*i),0));
    s=dsAdd(s,st);c=dsAdd(c,ct);
  }
}
vec2 gdAtan(vec2 x) {
  float seed=atan(x.x);vec2 s,c;gdSinCos(vec2(seed,0),s,c);
  vec2 r=dsDiv(dsSub(dsMul(x,c),s),dsAdd(c,dsMul(x,s)));
  return dsAdd(vec2(seed,0),dsSub(r,dsDiv(dsMul(dsMul(r,r),r),vec2(3,0))));
}
vec2 gdAcos(vec2 x) {
  vec2 ax=x.x<0.?-x:x;
  vec2 ratio=dsDiv(dsSub(vec2(1,0),ax),dsAdd(vec2(1,0),ax));
  vec2 angle=gdAtan(gdSqrt(ratio))*2.;
  return x.x<0.?dsSub(vec2(3.1415927410125732,-8.742278000372485e-8),angle):angle;
}

bool gdUncertain=false;bool gdUsedWide=false;

float gfC(float a){return a;}float gfF(float a){return a;}
float gfA(float a,float b){return a+b;}float gfS(float a,float b){return a-b;}
float gfM(float a,float b){return a*b;}float gfD(float a,float b){return a/b;}
bool gfZ(float a){return a==0.;}bool gfEQ(float a,float b){return a==b;}
float gfSQ(float a){return sqrt(max(0.,a));}float gfCB(float a){return sign(a)*pow(abs(a),1./3.);}
float gfAC(float a){return acos(clamp(a,-1.,1.));}void gfSC(float a,out float s,out float c){s=sin(a);c=cos(a);}
const float gfEPS=0.0000152587890625;

vec2 gpC(float a){return vec2(a,0);}float gpF(vec2 a){return dsFloat(a);}
vec2 gpA(vec2 a,vec2 b){return dsAdd(a,b);}vec2 gpS(vec2 a,vec2 b){return dsSub(a,b);}
vec2 gpM(vec2 a,vec2 b){return dsMul(a,b);}vec2 gpD(vec2 a,vec2 b){return dsDiv(a,b);}
bool gpZ(vec2 a){return all(equal(a,vec2(0)));}bool gpEQ(vec2 a,vec2 b){return all(equal(a,b));}
vec2 gpSQ(vec2 a){return gdSqrt(a);}vec2 gpCB(vec2 a){return gdCbrt(a);}
vec2 gpAC(vec2 a){return gdAcos(a);}void gpSC(vec2 a,out vec2 s,out vec2 c){gdSinCos(a,s,c);}
const float gpEPS=4.547473508864641e-13;
// Direct formula adapted from native/include/hopf/quartic.hpp.
// Ferrari/Cardano attribution: Nick Thompson 2021, Boost Software License.
// float and gf prefix are instantiated for float and paired float arithmetic.
struct gfRoots { float v[4]; int n; };
gfRoots gfEmpty(){gfRoots r;r.n=0;for(int i=0;i<4;++i)r.v[i]=gfC(0.);return r;}
void gfPush(inout gfRoots r,float x){
  for(int i=0;i<4;++i)if(i<r.n&&gfEQ(r.v[i],x))return;
  if(r.n<4)r.v[r.n++]=x;else gdUncertain=true;
  if(isnan(gfF(x))||isinf(gfF(x)))gdUncertain=true;
}
void gfGuard(float value,float magnitude){
  if(magnitude>0.&&abs(gfF(value))<=gfEPS*magnitude)gdUncertain=true;
}
gfRoots gfQuadratic(float a,float b,float c){
