  if((gpF(f[4])>0.&&gpF(f[2])>0.&&gpF(f[0])>0.)||(gpF(f[4])<0.&&gpF(f[2])<0.&&gpF(f[0])<0.)){
    vec2 m1=gpS(gpM(gpC(2.),gpM(f[4],f[2])),gpM(f[3],f[3]));
    vec2 m2=gpS(gpM(gpC(2.),gpM(f[2],f[0])),gpM(f[1],f[1]));
